from dataclasses import dataclass

@dataclass
class Point:
    x: float
    y: float

@dataclass
class Rectangle:
    width: float
    height: float

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

p = Point(3.0, 4.0)
r = Rectangle(5.0, 3.0)

print(f"Point: {p}")
print(f"Rectangle: {r}")
print(f"Area: {r.area()}")
print(f"Perimeter: {r.perimeter()}")
print(f"Point x: {p.x}")
